    ApplyWordMarkers = [==[
					return function(comp, tool)
						-- Get timeline item that contains this composition
						local getTimelineItem = loadstring(tool:GetData("GetTimelineItem"))()
						local item = getTimelineItem(comp)
						if not item then return end

						-- Get follower delay spline
						local spline = loadstring(tool:GetData("GetDelaySpline"))()(comp, tool)

						-- Get comp offset
						local offset = comp:GetAttrs("COMPN_RenderStart")
						local compositionEndFrame = comp:GetAttrs("COMPN_RenderEnd") or 1000
						local maxFrame = math.max(1, compositionEndFrame - 1)

						-- Animation lead-in: the follower spline must start changing before the
						-- spoken word starts, so the word is fully visible by the time it is spoken.
						local fps = tonumber(comp:GetPrefs("Comp.FrameFormat.Rate")) or 30
						local animationLength = tool:GetInput("AnimationLength") or 0
						local animationMode = tool:GetInput("AnimationMode") or 2
						local leadInFrames = animationMode == 1 and 0 or math.floor(animationLength * fps * 0.5 + 0.5)

						-- Collect marker positions from timeline; preserve the spoken end frame stored in the note.
						local markers = item:GetMarkers()
						local markerFrames = {}
						for frame, markerInfo in pairs(markers) do
							if markerInfo["customData"] == "AutoSubs" then
								table.insert(markerFrames, {
									frame = math.min(frame - offset, maxFrame),
									storedEnd = tonumber(markerInfo["note"]) or nil,
								})
							end
						end

						-- Sort markers by frame number
						table.sort(markerFrames, function(a, b) return a.frame < b.frame end)

						-- Split text into words
						local text = tool:GetInput("Text")
						local words = {}
						for word in text:gmatch("%S+") do
							table.insert(words, word)
						end
						
						-- UTF-8 aware character count
						local function utf8len(s)
							local _, count = s:gsub("[^\128-\191]", "")
							return count
						end

						-- Keyword flags are per word position; carry them over from the
						-- current timing so marker edits don't drop keyword colouring.
						local previousTiming = tool:GetData("WordTiming") or {}

						-- Build intermediate word timing format
						local wordTiming = {}
						local count = math.min(#markerFrames, #words)
						local charIndex = 0
						
						for i = 1, count do
							local wordText = words[i]
							if i > 1 then
								wordText = " " .. wordText
							end

							local length = utf8len(wordText)
							-- Markers denote when the word becomes visible; store the spoken start
							-- time as the marker plus the animation lead-in. The note carries the
							-- original spoken end frame so unchanged markers round-trip without
							-- rewriting word intervals.
							local marker = markerFrames[i]
							local startFrame = math.min(marker.frame + leadInFrames, maxFrame)
							local endFrame
						
							if marker.storedEnd then
								endFrame = marker.storedEnd
							elseif i < count then
								endFrame = markerFrames[i + 1].frame + leadInFrames
							else
								endFrame = maxFrame
							end

							if i < count then
								endFrame = math.min(endFrame, math.min(markerFrames[i + 1].frame + leadInFrames, maxFrame))
							end
						
							local previous = previousTiming[i]
							local isKeyword = previous ~= nil and (previous.keyword == true or previous.keyword == 1)

							table.insert(wordTiming, {
								["startIndex"] = charIndex,
								["endIndex"] = charIndex + length - 1,
								["startFrame"] = startFrame,
								["endFrame"] = endFrame,
								["keyword"] = isKeyword,
							})

							charIndex = charIndex + length
						end

						-- Normalize the marker-derived timing so duplicate or out-of-range marker
						-- positions don't collapse highlight states onto the same frame.
						wordTiming = loadstring(tool:GetData("ScaleWordTiming"))()(comp, wordTiming, true)

						-- Apply word timing (update spline, store data, refresh highlight)
						loadstring(tool:GetData("ApplyWordTiming"))()(comp, tool, wordTiming)

						-- Clean up markers
						while item:DeleteMarkerByCustomData("AutoSubs") do end
					end
