    ApplyHighlight = [==[
					return function(comp, tool)
						local STYLES = {"Fill", "Outline", "Shadow", "Bubble"}
						local STYLE_INDEX = {
							Fill = 1,
							Outline = 2, 
							Shadow = 3,
							Bubble = 4
						}
						local CHANNELS = { "Red", "Green", "Blue" } -- exclude opacity for now as it interferes with other effects
						local INTERNAL_CODES = { Red = 2401, Green = 2402, Blue = 2403, Enabled = 2000 } -- Note: Opacity = 2600

						loadstring(tool:GetData("UpdateAllStyleColors"))()(comp, tool)

						-- Function to retrieve the base style for non-highlighted words
						-- @param template: The template tool
						-- @param styleKey: The style key (e.g. "Fill", "Outline", etc.)
						-- @return: A table containing the base style values
						local function get_current_style(styleKey)
							local base = {}
							
							-- Get color values for all channels (Red, Green, Blue)
							for _, channel in ipairs(CHANNELS) do
								base[channel] = tool:GetInput(styleKey .. "Color" .. channel)
							end

							-- Handle enabled state differently for Bubble vs other styles
							local template = comp:FindTool("Template")
							local isBubbleStyle = styleKey == "Bubble"

							-- Bubble must be enabled at the template level or will not work with character-level styling
							template:SetInput("Enabled4", isBubbleStyle and 1 or 0)

							if isBubbleStyle then
								base["Enabled"] = 0 -- only highlighted words should have bubble enabled (disabled for base style)
							else
								base["Enabled"] = tool:GetInput(styleKey .. "Enabled")
							end

							return base
						end

						-- Keyword colouring: words flagged `keyword` in WordTiming are drawn in the
						-- Keyword Color through the Fill style (style index 0), whatever the
						-- highlight style is. The active word still wins when highlighting Fill.
						local FILL_STYLE_ID = 0
						local KEYWORD_CODES = { Red = 2401, Green = 2402, Blue = 2403 }
						local keywordEnabled = (tool:GetInput("KeywordEnabled") or (tool:GetData("AutoSubsKeyword") or {}).Enabled) == 1
						local keywordColor = {
							Red = (tool:GetInput("KeywordColorRed") or (tool:GetData("AutoSubsKeyword") or {}).Red),
							Green = (tool:GetInput("KeywordColorGreen") or (tool:GetData("AutoSubsKeyword") or {}).Green),
							Blue = (tool:GetInput("KeywordColorBlue") or (tool:GetData("AutoSubsKeyword") or {}).Blue),
						}
						local function is_keyword(word)
							return keywordEnabled and (word.keyword == true or word.keyword == 1)
						end

						-- Build a StyledText Array where word at `activeIndex` uses `highlight` colors and the rest use `base`
						-- (or the keyword colour for keyword words)
						local function build_style_array(wordTiming, activeIndex, highlight, base, styleId)
							local array = {}
							local keywordFill = {
								Red = keywordColor.Red,
								Green = keywordColor.Green,
								Blue = keywordColor.Blue,
								Enabled = base.Enabled
							}
							for j, word in ipairs(wordTiming) do
								local isActive = j == activeIndex
								local style = isActive and highlight or base
								if styleId == FILL_STYLE_ID and not isActive and is_keyword(word) then
									style = keywordFill
								end
								for key, internalCode in pairs(INTERNAL_CODES) do
									table.insert(array, {
										internalCode,
										word.startIndex,
										word.endIndex,
										Value = style[key],
										__flags = 256,
										Index = styleId
									})
								end
								-- Highlight drawn on Outline/Shadow/Bubble: colour the keyword's fill separately.
								if styleId ~= FILL_STYLE_ID and is_keyword(word) then
									for key, internalCode in pairs(KEYWORD_CODES) do
										table.insert(array, {
											internalCode,
											word.startIndex,
											word.endIndex,
											Value = keywordColor[key],
											__flags = 256,
											Index = FILL_STYLE_ID
										})
									end
								end
							end
							return array
						end

						-- Create a single StyledText keyframe value
						local function make_keyframe(index, styleArray)
							return {
								index,
								Value = {
									__ctor = "StyledText", -- internal id to designate this as a StyledText object
									Array = styleArray,
									Flags = { StepIn = true, LockedY = true, __flags = 256 }
								},
							}
						end

						local function round(x)
							return math.floor(x + 0.5)
						end

						local follower = comp:FindTool("Follower1")
						local characterLevelStyling = follower.Text:GetConnectedOutput():GetTool()
						local spline = characterLevelStyling.CharacterLevelStyling:GetConnectedOutput():GetTool()

						local wordTiming = tool:GetData("WordTiming")

						local highlight = {
    						Red = tool:GetInput("HighlightColorRed"),
    						Green = tool:GetInput("HighlightColorGreen"),
    						Blue = tool:GetInput("HighlightColorBlue"),
							Enabled = 1
						}

						-- (0=Fill, 1=Outline, 2=Shadow, 3=Bubble)
						local styleId = tool:GetInput("HighlightStyle")

						-- TextPlus input suffixes are 1-based (e.g. Red1, Red2).
						-- CharacterLevelStyling style indices appear to be 0-based.

						-- local animationLength = comp:FindTool("Template"):GetInput("AnimationLength")
						-- local fps = tonumber(comp:GetPrefs("Comp.FrameFormat.Rate")) or 30
						-- local transitionFrames = round(animationLength * fps)
						local transitionFrames = 0

						-- +1 required: styleId is 0-based but Lua arrays are 1-based
						local styleKey = STYLES[styleId + 1]
						local base = get_current_style(styleKey)
						local compositionEndFrame = comp:GetAttrs("COMPN_RenderEnd") or 1000
						local maxFrame = math.max(1, compositionEndFrame - 1)

						local keyframes = {}
						local keyframeIndex = 0
						for i, word in ipairs(wordTiming) do
							local revealFrame = word.revealFrame or word.startFrame
							local rawStartFrame = revealFrame + (i > 1 and transitionFrames or 0)
							local startFrame = math.min(rawStartFrame, maxFrame)
							local styleArray = build_style_array(wordTiming, i, highlight, base, styleId)

							keyframes[startFrame] = make_keyframe(keyframeIndex, styleArray)
							keyframeIndex = keyframeIndex + 1

							if i < #wordTiming then
								-- Holds the style constant until just before the next word is revealed,
								-- so the transition only occurs near the word boundary rather than fading
								-- from the beginning of the current word all the way to the next.
								local nextReveal = wordTiming[i + 1].revealFrame or wordTiming[i + 1].startFrame
								local holdFrame = math.min(math.min(word.endFrame - 1, nextReveal - 1), maxFrame)
								if holdFrame >= startFrame then
									keyframes[holdFrame] = make_keyframe(keyframeIndex, styleArray)
									keyframeIndex = keyframeIndex + 1
								end
							end
						end

						spline:SetKeyFrames(keyframes, true)
					end
]==],
    RemoveHighlight = [==[
					return function(comp, tool)
						local follower = comp:FindTool("Follower1")
						local characterLevelStyling = follower.Text:GetConnectedOutput():GetTool()
						local spline = characterLevelStyling.CharacterLevelStyling:GetConnectedOutput():GetTool()
						loadstring(tool:GetData("UpdateAllStyleColors"))()(comp, tool)

						-- Keyword words keep their Keyword Color (Fill style, index 0) without
						-- the highlighter. No keywords (or Color Keywords off) leaves the array
						-- empty, which uses default styling.
						local styleArray = {}
						if (tool:GetInput("KeywordEnabled") or (tool:GetData("AutoSubsKeyword") or {}).Enabled) == 1 then
							local KEYWORD_CODES = { Red = 2401, Green = 2402, Blue = 2403 }
							local keywordColor = {
								Red = (tool:GetInput("KeywordColorRed") or (tool:GetData("AutoSubsKeyword") or {}).Red),
								Green = (tool:GetInput("KeywordColorGreen") or (tool:GetData("AutoSubsKeyword") or {}).Green),
								Blue = (tool:GetInput("KeywordColorBlue") or (tool:GetData("AutoSubsKeyword") or {}).Blue),
							}
							for _, word in ipairs(tool:GetData("WordTiming") or {}) do
								if word.keyword == true or word.keyword == 1 then
									for key, internalCode in pairs(KEYWORD_CODES) do
										table.insert(styleArray, {
											internalCode,
											word.startIndex,
											word.endIndex,
											Value = keywordColor[key],
											__flags = 256,
											Index = 0
										})
									end
								end
							end
						end
						-- Lets UpdateHighlight know there is keyword styling to clear later.
						tool:SetData("KeywordStyled", #styleArray > 0 and 1 or 0)

						local keyframes = {
							[0] = {
						        0,                         -- index of keyframe in the array (0-based) - kinda random - why?
						        Value = {
						            __ctor = "StyledText", -- internal id to designate this as a StyledText object
						            Array = styleArray, -- empty array uses default styling
						            Flags = { StepIn = true, LockedY = true, __flags = 256 }
						        },
						    },
						}

						spline:SetKeyFrames(keyframes, true)

						-- Disable Bubble (enabled specifically for highlight)
						local template = comp:FindTool("Template")
						template:SetInput("Enabled4", 0)
					end
]==],
    UpdateHighlight = [==[
					return function(comp, tool)
						-- Must update Highlight keyframes (if enabled)
						local isEnabled = tool:GetInput("HighlightEnabled") == 1
						if isEnabled then
    					    loadstring(tool:GetData("ApplyHighlight"))()(comp, tool)
						else
							-- Highlight off: keyword words still need their colour keyframe
							-- (RemoveHighlight writes it). Skipped when there is nothing to
							-- colour and nothing to clear, so captions without keywords
							-- behave exactly as before.
							local hasKeywords = false
							if (tool:GetInput("KeywordEnabled") or (tool:GetData("AutoSubsKeyword") or {}).Enabled) == 1 then
								for _, word in ipairs(tool:GetData("WordTiming") or {}) do
									if word.keyword == true or word.keyword == 1 then
										hasKeywords = true
										break
									end
								end
							end
							if hasKeywords or tool:GetData("KeywordStyled") == 1 then
								loadstring(tool:GetData("RemoveHighlight"))()(comp, tool)
							end
						end
					end
]==],
